import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.Desnpdez.js";const g=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"help/faq.md","filePath":"help/faq.md"}'),s={name:"help/faq.md"};function n(i,e,d,l,h,p){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="what-is-mindbehindai" tabindex="-1">What is MindBehindAI? <a class="header-anchor" href="#what-is-mindbehindai" aria-label="Permalink to &quot;What is MindBehindAI?&quot;">​</a></h2><p>A desktop app for <strong>macOS</strong> and <strong>Windows</strong> that runs a local <strong>assistant bridge</strong> and lets you attach <strong>connections</strong> (tools and data) for use in assistants such as ChatGPT, MBIT Chat, or other MCP-capable clients.</p><h2 id="do-i-need-docker" tabindex="-1">Do I need Docker? <a class="header-anchor" href="#do-i-need-docker" aria-label="Permalink to &quot;Do I need Docker?&quot;">​</a></h2><p><strong>Not for the bridge.</strong> A normal install includes the engine on your computer.<br> Some <strong>Library</strong> presets show a <strong>Docker</strong> badge—only those presets need Docker installed.</p><h2 id="does-my-data-go-to-mindbehind-servers" tabindex="-1">Does my data go to MindBehind servers? <a class="header-anchor" href="#does-my-data-go-to-mindbehind-servers" aria-label="Permalink to &quot;Does my data go to MindBehind servers?&quot;">​</a></h2><p>Your documents and tool traffic stay on your computer. The app still talks to the internet for things you expect: <strong>license checks</strong>, <strong>remote MCP endpoints</strong> you configured, <strong>OAuth</strong> in the browser, and optional <strong>MBIT Chat sync</strong> when you turn it on.</p><h2 id="which-platforms-are-supported" tabindex="-1">Which platforms are supported? <a class="header-anchor" href="#which-platforms-are-supported" aria-label="Permalink to &quot;Which platforms are supported?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Platform</th><th>Install</th></tr></thead><tbody><tr><td><strong>macOS</strong> (Apple Silicon)</td><td><a href="https://halfcross.github.io/mbit-mcpo-proxy-download/" target="_blank" rel="noreferrer">Download page</a> — Terminal script or <code>.dmg</code></td></tr><tr><td><strong>Windows</strong> (64-bit portable)</td><td><a href="https://github.com/halfcross/mbit-mcpo-proxy-download/releases" target="_blank" rel="noreferrer">GitHub Releases</a> — single <code>.exe</code></td></tr></tbody></table><p><strong>Linux</strong> desktop builds are not offered in this product line. Intel Macs are not supported in current macOS releases.</p><h2 id="where-is-my-configuration-stored" tabindex="-1">Where is my configuration stored? <a class="header-anchor" href="#where-is-my-configuration-stored" aria-label="Permalink to &quot;Where is my configuration stored?&quot;">​</a></h2><p><strong>macOS:</strong></p><p><code>~/Library/Application Support/MindBehind/mcp-orchestrator/</code></p><p><strong>Windows:</strong></p><p><code>%APPDATA%\\MindBehind\\mcp-orchestrator\\</code></p><p>See <strong><a href="./../reference/data-directory.html">Data directory</a></strong> for a file-by-file list.</p><h2 id="how-do-i-update" tabindex="-1">How do I update? <a class="header-anchor" href="#how-do-i-update" aria-label="Permalink to &quot;How do I update?&quot;">​</a></h2><p>Use the <strong><a href="https://halfcross.github.io/mbit-mcpo-proxy-download/" target="_blank" rel="noreferrer">download page</a></strong> or <a href="https://github.com/halfcross/mbit-mcpo-proxy-download/releases" target="_blank" rel="noreferrer">public releases</a>:</p><ul><li><strong>macOS:</strong> download the new <code>.dmg</code> from <a href="https://github.com/halfcross/mbit-mcpo-proxy-download/releases" target="_blank" rel="noreferrer">Releases</a> and replace the app in Applications (or use the legacy install script below).</li><li><strong>Windows:</strong> download the new portable <code>.exe</code> and run it (replace your previous copy if you keep one folder).</li></ul><p>You can also check <strong>About → Updates</strong> inside the app for release notes and links.</p><p><strong>macOS (legacy Terminal install):</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://halfcross.github.io/mbit-mcpo-proxy-download/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span></span></code></pre></div><p>Prefer downloading the <code>.dmg</code> directly from the <a href="https://halfcross.github.io/mbit-mcpo-proxy-download/" target="_blank" rel="noreferrer">download page</a> or <a href="https://github.com/halfcross/mbit-mcpo-proxy-download/releases" target="_blank" rel="noreferrer">Releases</a>.</p><h2 id="can-i-import-from-claude-desktop" tabindex="-1">Can I import from Claude Desktop? <a class="header-anchor" href="#can-i-import-from-claude-desktop" aria-label="Permalink to &quot;Can I import from Claude Desktop?&quot;">​</a></h2><p><strong>macOS:</strong> copy the <code>mcpServers</code> block from <code>~/Library/Application Support/Claude/claude_desktop_config.json</code> (or similar) and use <strong><a href="./../everyday/settings.html#import-json-mcpjson">Settings → Import JSON</a></strong>.</p><h2 id="why-does-windows-warn-or-start-slowly" tabindex="-1">Why does Windows warn or start slowly? <a class="header-anchor" href="#why-does-windows-warn-or-start-slowly" aria-label="Permalink to &quot;Why does Windows warn or start slowly?&quot;">​</a></h2><p>Portable builds are <strong>not code-signed</strong> yet, so <strong>SmartScreen</strong> may show “Windows protected your PC”—use <strong>More info → Run anyway</strong> after downloading from the official release page. The <strong>first launch</strong> can take <strong>20–30 seconds</strong> while the app unpacks and <strong>Defender</strong> scans it; later starts are usually faster. Optional Defender folder exclusions and a hidden-window fix are in <strong><a href="./troubleshooting.html#windows">Troubleshooting → Windows</a></strong>.</p><h2 id="need-more-help" tabindex="-1">Need more help? <a class="header-anchor" href="#need-more-help" aria-label="Permalink to &quot;Need more help?&quot;">​</a></h2><p>Open <strong><a href="./troubleshooting.html">Troubleshooting</a></strong> next.</p>',29)])])}const u=o(s,[["render",n]]);export{g as __pageData,u as default};
